import test from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs'
import * as T from 'three'
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js'
import {createRemy} from '../src/karakurt/assets.js'

// Retain the production skin and all clips; omit image decoding in Node only.
async function readModel(){
 const base=new URL('../public/models/',import.meta.url)
 const j=JSON.parse(fs.readFileSync(new URL('remy-karakurt.gltf',base)))
 for(const b of j.buffers)b.uri='data:application/octet-stream;base64,'+fs.readFileSync(new URL(b.uri,base)).toString('base64')
 j.images=[];j.textures=[];j.materials=[]
 for(const mesh of j.meshes)for(const primitive of mesh.primitives)delete primitive.material
 globalThis.ProgressEvent??=class ProgressEvent {constructor(type,properties){this.type=type;Object.assign(this,properties)}}
 return new GLTFLoader().parseAsync(JSON.stringify(j),'')
}
for(const state of ['Walk','Run'])test(`Production ${state} alternates feet instead of bouncing a frozen pose`,async()=>{
 const person=createRemy(await readModel()),bones={}
 person.traverse(n=>{if(n.isBone)bones[n.name.replace(/^mixamorig[:_]?/,'')]=n})
 person.userData.setState(state);person.userData.update(.3)
 const samples=[]
 for(let i=0;i<120;i++){
  person.userData.update(1/120);person.updateMatrixWorld(true)
  samples.push(Object.fromEntries(['LeftFoot','RightFoot','Hips'].map(n=>[n,bones[n].getWorldPosition(new T.Vector3())])))
 }
 const range=(n,axis)=>Math.max(...samples.map(s=>s[n][axis]))-Math.min(...samples.map(s=>s[n][axis]))
 for(const foot of ['LeftFoot','RightFoot'])assert.ok(range(foot,'z')>.35,`${foot} must swing relative to the stationary AI root`)
 const difference=samples.map(s=>s.LeftFoot.z-s.RightFoot.z)
 assert.ok(Math.min(...difference)<-.15&&Math.max(...difference)>.15,'left and right feet must exchange lead')
 assert.ok(range('Hips','y')<.25,'hip bob must not become a jump')
 assert.ok(samples.every(s=>Math.abs(s.Hips.x-samples[0].Hips.x)<.001&&Math.abs(s.Hips.z-samples[0].Hips.z)<.001),'AI, not the clip, owns horizontal root travel')
 console.log(state,'foot swing',range('LeftFoot','z'),range('RightFoot','z'),'hip bob',range('Hips','y'))
})
test('Production Remy skin carries the slipper through the authored strike',async()=>{
 const gltf=await readModel(),slipper=new T.Mesh(new T.BoxGeometry(.13,.58,.065))
 const person=createRemy(gltf,{Slipper:slipper}),grip=person.getObjectByName('SlipperGrip')
 assert.ok(grip,'actual exported right hand must receive prop')
 person.userData.setState('Attack');const points=[]
 for(let i=0;i<80;i++){person.userData.update(1/30);person.updateMatrixWorld(true);points.push(grip.getWorldPosition(new T.Vector3()))}
 const bounds=new T.Box3().setFromPoints(points).getSize(new T.Vector3())
 assert.ok(Math.max(bounds.x,bounds.y,bounds.z)>.4,'strike must visibly move the hand-held prop')
